spec.setup_code:
var T = 14;
var B = [0, 4.2, 7, 10.4, 14];
var CAP = ['local attention: 32 query atoms see 128 neighbours', 'aggregate atoms → tokens', 'global attention, biased by the pair representation z', 'atom decoder: tokens split back into atoms'];
var TABL = ['atom encoder', 'aggregate', 'token transformer', 'atom decoder'];
var TABS = ['encoder', 'aggregate', 'transformer', 'decoder'];
var SH = ['#9DBBE8', '#EBB99C'];
function mk(s) { return function () { s |= 0; s = s + 0x6D2B79F5 | 0; var q = Math.imul(s ^ s >>> 15, 1 | s); q = q + Math.imul(q ^ q >>> 7, 61 | q) ^ q; return ((q ^ q >>> 14) >>> 0) / 4294967296; }; }
var rnd = mk(7);
function cl(x) { return Math.min(1, Math.max(0, x)); }
function ss(a, b, x) { var u = cl((x - a) / (b - a)); return u * u * (3 - 2 * u); }
function eio(x) { x = cl(x); return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2; }
function mem(x, a, b) { return ss(a - 0.5, a + 0.5, x) * (1 - ss(b - 0.5, b + 0.5, x)); }
var NA = 40, NR = 8;
var Z = [], i, j;
for (i = 0; i < NR; i++) Z.push([]);
for (i = 0; i < NR; i++) for (j = i; j < NR; j++) {
  var zz = 0.1 + 0.9 * cl(0.5 * Math.exp(-Math.abs(i - j) / 2.2) + 0.55 * rnd() - 0.08);
  if (i === j) zz = 0.95;
  Z[i][j] = zz; Z[j][i] = zz;
}
var ANG = [], LEN = [];
for (i = 0; i < NA; i++) { ANG.push((rnd() < 0.5 ? -1 : 1) * Math.PI / 2 + (rnd() - 0.5) * 1.3); LEN.push(0.75 + rnd() * 0.8); }
function prog(k, u) { var d = (k % 5) / 4 * 0.35; return eio((u - d) / 0.65); }
function head(c, x, y, a, s) {
  c.beginPath(); c.moveTo(x, y);
  c.lineTo(x - s * Math.cos(a - 0.45), y - s * Math.sin(a - 0.45));
  c.lineTo(x - s * Math.cos(a + 0.45), y - s * Math.sin(a + 0.45));
  c.closePath(); c.fill();
}
function fit(c, txt, maxW, s0) {
  var s = s0; c.font = s + 'px sans-serif';
  while (s > 11 && c.measureText(txt).width > maxW) { s--; c.font = s + 'px sans-serif'; }
}
return {
  draw: function (c, W, H, time, dt) {
    var t = time % T;
    c.globalAlpha = 1; c.fillStyle = '#ffffff'; c.fillRect(0, 0, W, H);
    c.textAlign = 'center'; c.textBaseline = 'middle';
    var m = Math.max(18, W * 0.04), left = m, right = W - m;
    var sp = (right - left) / NA, tsp = (right - left) / NR;
    var y0 = H * 0.40, rA = Math.max(2, Math.min(3.6, sp * 0.32)), rT = Math.min(18, tsp * 0.4);
    var ph = t < B[1] ? 0 : t < B[2] ? 1 : t < B[3] ? 2 : 3;
    var hx = [], hy = [], p = [], rp = [], r, k;
    for (r = 0; r < NR; r++) rp.push(0);
    for (i = 0; i < NA; i++) {
      hx.push(left + (i + 0.5) * sp);
      hy.push(y0 + 7 * Math.sin(i * 1.3) + 4 * Math.sin(i * 0.55));
      var pp = t < 9 ? prog(i, (t - B[1]) / 2.6) : 1 - prog(i, (t - B[3]) / 2.2);
      p.push(pp); rp[Math.floor(i / 5)] += pp / 5;
    }
    var tx = function (q) { return left + (q + 0.5) * tsp; };
    // caption
    var ca = ss(B[ph], B[ph] + 0.5, t) * (1 - ss(B[ph + 1] - 0.4, B[ph + 1], t));
    c.globalAlpha = ca; c.fillStyle = '#04204B';
    fit(c, CAP[ph], W - 16, 13);
    c.fillText(CAP[ph], W / 2, 22);
    c.globalAlpha = 1;
    // phase 1: local attention window
    var w1 = ss(0, 0.4, t) * (1 - ss(4.0, 4.4, t));
    var q0 = eio((t - 0.2) / 3.7) * (NA - 4);
    var X = function (q) { return left + q * sp; };
    if (w1 > 0.01) {
      var ka = q0 - 6, kb = q0 + 10;
      c.globalAlpha = w1;
      var kx0 = Math.max(left - 3, X(ka)), kx1 = Math.min(right + 3, X(kb));
      c.setLineDash([4, 3]); c.strokeStyle = '#8098BC'; c.lineWidth = 1;
      c.strokeRect(kx0, y0 - 30, kx1 - kx0, 60);
      c.setLineDash([]);
      c.fillStyle = 'rgba(11,79,192,0.13)'; c.strokeStyle = '#0B4FC0';
      c.fillRect(X(q0), y0 - 20, 4 * sp, 40); c.strokeRect(X(q0), y0 - 20, 4 * sp, 40);
      c.strokeStyle = '#0B4FC0'; c.lineWidth = 0.7;
      for (i = 0; i < NA; i++) {
        var wq = mem(i + 0.5, q0, q0 + 4);
        if (wq < 0.03) continue;
        for (j = 0; j < NA; j++) {
          if (j === i) continue;
          var wk = mem(j + 0.5, ka, kb) * wq;
          if (wk < 0.03) continue;
          var dx = hx[j] - hx[i], ax = hx[i], ay = hy[i] - rA, bx = hx[j], by = hy[j] - rA;
          c.globalAlpha = w1 * wk * 0.3;
          c.beginPath(); c.moveTo(ax, ay);
          c.quadraticCurveTo((ax + bx) / 2, Math.min(ay, by) - 8 - Math.min(34, Math.abs(dx) * 0.45), bx, by);
          c.stroke();
        }
      }
      c.globalAlpha = 1;
    }
    // residue brackets and labels
    for (r = 0; r < NR; r++) {
      var ra = 1 - rp[r];
      if (ra < 0.02) continue;
      c.globalAlpha = ra * 0.9;
      c.strokeStyle = r % 2 ? '#B4552F' : '#0B4FC0'; c.lineWidth = 2;
      c.beginPath(); c.moveTo(X(5 * r) + 2, y0 + 30); c.lineTo(X(5 * r + 5) - 2, y0 + 30); c.stroke();
      c.fillStyle = '#3D5F91'; c.font = '11px sans-serif';
      c.fillText('r' + (r + 1), tx(r), y0 + 43);
    }
    c.globalAlpha = 1;
    // atoms
    var k0;
    for (i = 0; i < NA; i++) {
      r = Math.floor(i / 5);
      var pi = p[i], ax2 = hx[i] + (tx(r) - hx[i]) * pi, ay2 = hy[i] + (y0 - hy[i]) * pi;
      var al = 1 - ss(0.75, 1, pi);
      var inq = 0;
      if (w1 > 0.01) {
        var mk2 = mem(i + 0.5, q0 - 6, q0 + 10);
        al *= 1 - 0.55 * w1 * (1 - mk2);
        inq = mem(i + 0.5, q0, q0 + 4) * w1;
      }
      if (al < 0.02) continue;
      c.globalAlpha = al; c.fillStyle = SH[r % 2];
      c.beginPath(); c.arc(ax2, ay2, rA, 0, 6.2832); c.fill();
      if (inq > 0.3) { c.globalAlpha = al * inq; c.strokeStyle = '#0B4FC0'; c.lineWidth = 1.2; c.stroke(); }
    }
    c.globalAlpha = 1;
    // tokens
    var w3 = ss(B[2], B[2] + 0.4, t) * (1 - ss(B[3] - 0.4, B[3], t));
    var ai = Math.min(7, Math.max(0, Math.floor((t - 7.1) / 0.42)));
    for (r = 0; r < NR; r++) {
      var g = rp[r];
      if (g < 0.02) continue;
      var rad = rT * g;
      c.globalAlpha = Math.min(1, g * 1.3);
      c.fillStyle = SH[r % 2]; c.strokeStyle = '#3D5F91'; c.lineWidth = 1;
      c.beginPath(); c.arc(tx(r), y0, rad, 0, 6.2832); c.fill(); c.stroke();
      if (g > 0.85) {
        c.globalAlpha = (g - 0.85) / 0.15; c.fillStyle = '#04204B'; c.font = '11px sans-serif';
        c.fillText('T' + (r + 1), tx(r), y0);
      }
    }
    c.globalAlpha = 1;
    // phase 3: global attention + pair bias grid
    if (w3 > 0.01) {
      var maxH = H * 0.15, pass, qi, qj;
      for (pass = 0; pass < 2; pass++) {
        for (qi = 0; qi < NR; qi++) {
          var act = qi === ai;
          if ((pass === 1) !== act) continue;
          for (qj = 0; qj < NR; qj++) {
            if (qj === qi) continue;
            var z = Z[qi][qj], up = qj < qi ? -1 : 1, dir = qi > qj ? 1 : -1;
            var d = Math.abs(qi - qj), hp = 10 + (maxH - 10) * (d - 1) / 6;
            var by2 = y0 + up * rT * 0.9, sx = tx(qj) + dir * rT * 0.35, ex = tx(qi) - dir * rT * 0.35;
            var cx = (sx + ex) / 2, cy = by2 + up * 2 * hp;
            c.globalAlpha = w3 * (act ? 0.3 + 0.7 * z : 0.1 + 0.25 * z);
            c.strokeStyle = act ? '#0B4FC0' : '#8098BC'; c.fillStyle = c.strokeStyle;
            c.lineWidth = act ? 0.6 + 3.4 * z : 0.4 + 1.6 * z;
            c.beginPath(); c.moveTo(sx, by2); c.quadraticCurveTo(cx, cy, ex, by2); c.stroke();
            head(c, ex, by2, Math.atan2(by2 - cy, ex - cx), act ? 4 + 3 * z : 3);
          }
        }
      }
      c.globalAlpha = w3; c.strokeStyle = '#0B4FC0'; c.lineWidth = 2;
      c.beginPath(); c.arc(tx(ai), y0, rT + 2, 0, 6.2832); c.stroke();
      // grid z
      var cs = Math.min(11, H * 0.03), gl = 'pair bias';
      c.font = '11px sans-serif';
      var lw = Math.max(c.measureText('thickness ∝ zᵢⱼ').width, c.measureText('query i = ' + (ai + 1)).width);
      var tot = NR * cs + 10 + lw, gx = (W - tot) / 2, gy = H * 0.64;
      for (qi = 0; qi < NR; qi++) for (qj = 0; qj < NR; qj++) {
        c.globalAlpha = w3; c.fillStyle = 'rgba(11,79,192,' + (0.06 + 0.8 * Z[qi][qj]).toFixed(2) + ')';
        c.fillRect(gx + qj * cs, gy + qi * cs, cs - 1, cs - 1);
      }
      c.globalAlpha = w3; c.strokeStyle = '#04204B'; c.lineWidth = 1.5;
      c.strokeRect(gx - 1, gy + ai * cs - 1, NR * cs + 1, cs + 1);
      c.textAlign = 'left'; c.fillStyle = '#04204B';
      c.fillText('pair bias z', gx + NR * cs + 10, gy + cs * 1.5);
      c.fillStyle = '#3D5F91';
      c.fillText('thickness ∝ zᵢⱼ', gx + NR * cs + 10, gy + cs * 3.5);
      c.fillText('query i = ' + (ai + 1), gx + NR * cs + 10, gy + cs * 5.5);
      c.textAlign = 'center'; c.globalAlpha = 1;
    }
    // phase 4: coordinate update arrows
    var ga = eio((t - 12.2) / 1.0) * (1 - ss(13.5, 14, t));
    if (ga > 0.01) {
      c.strokeStyle = '#138374'; c.fillStyle = '#138374'; c.lineWidth = 1.5; c.globalAlpha = ga;
      for (i = 0; i < NA; i++) {
        var L = Math.min(14, sp * LEN[i]) * ga / Math.max(ga, 0.001) * eio((t - 12.2) / 1.0);
        var sx2 = hx[i], sy2 = hy[i] + Math.sin(ANG[i]) * (rA + 1), ex2 = sx2 + Math.cos(ANG[i]) * L, ey2 = sy2 + Math.sin(ANG[i]) * L;
        c.beginPath(); c.moveTo(sx2, sy2); c.lineTo(ex2, ey2); c.stroke();
        head(c, ex2, ey2, ANG[i], 3);
      }
      c.globalAlpha = 1;
    }
    // bottom notes
    var ny = H - 40;
    c.font = '12px sans-serif';
    if (w1 > 0.01) {
      c.globalAlpha = w1; c.fillStyle = '#3D5F91';
      var a1 = Math.round(q0);
      c.fillText('query atoms ' + (a1 + 1) + '–' + (a1 + 4) + ' of ' + NA + ' (window sizes scaled down)', W / 2, ny - 20);
      var t1 = 'query block', t2 = 'key window';
      var w_1 = c.measureText(t1).width, w_2 = c.measureText(t2).width;
      var tt = 18 + w_1 + 26 + 22 + w_2, lx = (W - tt) / 2;
      c.fillStyle = 'rgba(11,79,192,0.13)'; c.strokeStyle = '#0B4FC0'; c.lineWidth = 1;
      c.fillRect(lx, ny - 5, 12, 10); c.strokeRect(lx, ny - 5, 12, 10);
      c.fillStyle = '#04204B'; c.textAlign = 'left'; c.fillText(t1, lx + 18, ny);
      var lx2 = lx + 18 + w_1 + 26;
      c.setLineDash([3, 2]); c.strokeStyle = '#8098BC'; c.strokeRect(lx2, ny - 6, 16, 12); c.setLineDash([]);
      c.fillText(t2, lx2 + 22, ny);
      c.textAlign = 'center'; c.globalAlpha = 1;
    }
    if (ph === 1) {
      c.globalAlpha = ss(B[1], B[1] + 0.5, t) * (1 - ss(B[2] - 0.4, B[2], t)); c.fillStyle = '#3D5F91';
      c.fillText('5 atoms of residue r flow into token T_r', W / 2, ny);
      c.globalAlpha = 1;
    }
    if (ph === 3) {
      c.globalAlpha = ss(B[3] + 1.5, B[3] + 2.2, t) * (1 - ss(13.6, 14, t)); c.fillStyle = '#138374';
      c.fillText('coordinate update Δx for every atom', W / 2, ny);
      c.globalAlpha = 1;
    }
    // tabs
    var cw = W / 4, names = W >= 640 ? TABL : TABS;
    c.font = '11px sans-serif';
    for (k = 0; k < 4; k++) {
      var on = k === ph;
      c.fillStyle = on ? '#0B4FC0' : '#8098BC';
      c.fillText(names[k], (k + 0.5) * cw, H - 18);
      c.globalAlpha = 0.35; c.fillStyle = '#8098BC';
      c.fillRect(k * cw + 8, H - 8, cw - 16, 2);
      c.globalAlpha = 1;
      if (on) { c.fillStyle = '#0B4FC0'; c.fillRect(k * cw + 8, H - 8, (cw - 16) * cl((t - B[k]) / (B[k + 1] - B[k])), 2); }
    }
    c.globalAlpha = 1;
  }
};
